#!/usr/bin/env bash
# Boots the official Mindustry v160.5 dedicated server with Singularity v7.3 and exercises: content (Astral Aegis and the
# tactical controllers gone, titans are 3D walkers, 3D drawers installed), Aurelia isolation (zero vanilla content shown
# on Aurelia), the Aurelia tech tree (own root, own items only, real research costs), Aurelia sector generation (own
# terrain / ores / start stock / waves, unit cap from the core, every Aurelia block buildable), every 3D unit alive,
# moving and firing (incl. the titans' own gait), the fabricator and the tide dock printing units, save/load.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)"; VENDOR="${VENDOR:-$HOME/.cache/vendor}"
JAVA_HOME="${JAVA_HOME:-$(find "$VENDOR" -maxdepth 1 -type d -name 'jdk-17*' | head -1)}"; JAVA="$JAVA_HOME/bin/java"
# static guard: a string-literal atlas lookup renders the error region ("oh no") in game
if grep -rn 'Draw\.rect("' "$ROOT/src" --include=*.java; then echo 'TEST FAILED: string-literal region draw in source'; exit 1; fi
TEST="$ROOT/testserver"; rm -rf "$TEST"; mkdir -p "$TEST/config/mods"; cp "$ROOT/dist/Singularity-v8.3-beta.jar" "$TEST/config/mods/"
cd "$TEST"; mkfifo cmd.fifo
HOME="$TEST" "$JAVA" -Xmx700m -jar "$VENDOR/server-release.jar" <cmd.fifo >server.log 2>&1 & PID=$!; exec 3>cmd.fifo
send(){ echo "$1" >&3; sleep "${2:-2}"; }
P='blackhole-'
sleep 12; send mods 2; send 'config autoPause false' 1
send 'js global.F=function(v,n){var k=Math.pow(10,n);return String(Math.round(Number(v)*k)/k);};global.free=function(cx,cy,rad){for(var r=6;r<120;r+=2)for(var a=0;a<360;a+=10){var q=Vars.world.tileWorld(cx+Math.cos(a/57.3)*r*8,cy+Math.sin(a/57.3)*r*8);if(q==null)continue;var ok=true;for(var dx=-rad;dx<=rad&&ok;dx++)for(var dy=-rad;dy<=rad&&ok;dy++){var z=Vars.world.tile(q.x+dx,q.y+dy);if(z==null||z.solid()||z.floor().isDeep()||z.build!=null)ok=false;}if(ok)return q;}return null;};global.se=function(n){return Vars.content.statusEffect(n);};global.sandbox="item-source item-void liquid-source liquid-void power-source power-void heat-source".split(" ");"helpers ready"' 1

# ---- content
send 'js "astral aegis present: "+(Vars.content.unit("'$P'astral-aegis")!=null)+", tactical controllers present: "+(Vars.content.block("'$P'titan-director-s")!=null||Vars.content.block("'$P'titan-director-e")!=null)+", units: "+Vars.content.units().select(function(u){return u.name.startsWith("'$P'")}).map(function(u){return u.name.substring(10)+"("+u.getClass().getSuperclass().getSimpleName()+")"}).toString(" ")' 1
send 'js var n=0,m=0;Vars.content.blocks().each(function(b){if(b.name.startsWith("'$P'")){m++;if(b instanceof Turret&&b.drawer.getClass().getSimpleName()=="DrawTurret3D")n++;}});"blackhole blocks="+m+", turrets with 3D drawer="+n' 1

# ---- Aurelia isolation: nothing vanilla may be shown on Aurelia (blocks, items, liquids, units, statuses)
send 'js var p=Vars.content.planet("'$P'aurelia");var bad=[],own=0,sb=0;[Vars.content.blocks(),Vars.content.items(),Vars.content.liquids(),Vars.content.units(),Vars.content.statusEffects()].forEach(function(l){l.each(function(c){if(c.isHidden&&c.isHidden())return;if(c instanceof Block&&!(c.isVisible()||c.isFloor()||c.isStatic()||c instanceof OreBlock||c instanceof Prop))return;if(!c.isOnPlanet(p))return;if(c.name.startsWith("'$P'"))own++;else if(global.sandbox.indexOf(c.name)>=0)sb++;else bad.push(c.name);});});"aurelia content: own="+own+", wanted vanilla sandbox sources/voids="+sb+", other vanilla shown on aurelia="+bad.length+(bad.length?" VANILLA "+bad.slice(0,30).join(" "):"")' 2

# ---- Aurelia tech tree: own root, own items, real costs
send 'js var p=Vars.content.planet("'$P'aurelia");var n=0,free=0,vanilla=[],foreignItem=[],total=0;var walk=function(t){n++;if(!t.content.name.startsWith("'$P'"))vanilla.push(t.content.name);var c=0;t.requirements.forEach(function(q){c+=q.amount;if(!q.item.name.startsWith("'$P'"))foreignItem.push(t.content.name+":"+q.item.name);});total+=c;if(c==0&&!(t.content instanceof Item||t.content instanceof Liquid||t.content==p.techTree.content))free++;t.children.each(walk);};walk(p.techTree);"aurelia tree: root="+p.techTree.content.name+" nodes="+n+" vanilla nodes="+vanilla.length+(vanilla.length?" VANILLA "+vanilla.join(" "):"")+" vanilla-item costs="+foreignItem.length+(foreignItem.length?" VANILLA "+foreignItem.join(" "):"")+" free non-resource nodes="+free+" total research items="+total+" unlocked on landing: "+p.unlockedOnLand.map(function(c){return c.name.substring(10)}).toString(" ")' 1
send 'js var p=Vars.content.planet("'$P'aurelia");var s="";p.techTree.children.each(function(c){s+=" "+c.content.name.substring(10)+"["+c.requirements.map(function(q){return q.item.name.substring(10)+"x"+q.amount}).toString(",")+"]";});"first research steps:"+s' 1

# ---- Aurelia sector generation
send 'host Ancient_Caldera survival' 10

# ---- 7.2: accretion foundry (new 4x4 crafter with the FoundryModel drawer) and the forge (3D model + v6.1 black hole) are
# ---- real content: both exist with 3D drawers, the foundry crafts degenerate matter from titanium + graphite, the forge keeps its recipe
send 'js var f=Vars.content.block("'$P'accretion-foundry"),g=Vars.content.block("'$P'singularity-forge");"foundry: "+(f==null?"MISSING":"size="+f.size+" drawer="+f.drawer.getClass().getSimpleName()+" out="+f.outputItem.item.name.substring(10)+"x"+f.outputItem.amount+" craftTime="+f.craftTime+" node="+(TechTree.all.find(function(n){return n.content==f;})!=null))+"; forge: "+(g==null?"MISSING":"size="+g.size+" drawer="+g.drawer.getClass().getSimpleName()+" out="+g.outputItem.item.name.substring(10)+"x"+g.outputItem.amount)' 1
send 'js var t=Vars.state.rules.defaultTeam;var c=t.core();var q=global.free(c.x,c.y,3);q.setNet(Vars.content.block("'$P'accretion-foundry"),t,0);var b=q.build;var fed=[];q.build.block.consumers.forEach(function(cons){if(cons instanceof ConsumeItems)cons.items.forEach(function(st){b.items.add(st.item,st.amount*6);fed.push(st.item.name.replace("'$P'","")+"x"+st.amount);});});b.power.status=1;var n=0;while(b.items.get(Vars.content.item("'$P'degenerate-matter"))==0&&n<2000){b.update();n++;}var res="foundry placed at "+q.x+","+q.y+" in: "+fed.join(",")+" -> crafted "+b.items.get(Vars.content.item("'$P'degenerate-matter"))+" degenerate matter after "+n+" ticks (progress "+global.F(b.progress,2)+", warmup "+global.F(b.warmup,2)+")"+(b.items.get(Vars.content.item("'$P'degenerate-matter"))>0?"":" printed nothing");b.tile.setNet(Blocks.air);res' 3
send 'js var t=Vars.state.rules.defaultTeam;var c=t.core();var q=global.free(c.x,c.y,3);q.setNet(Vars.content.block("'$P'singularity-forge"),t,0);var b=q.build;var g=b.block;b.power.status=1;var reqs=[];g.consumers.forEach(function(cons){if(cons instanceof ConsumeItems){cons.items.forEach(function(st){b.items.add(st.item,st.amount*4);reqs.push(st.item.name+"x"+st.amount);});}});var n=0;while(b.items.get(g.outputItem.item)==0&&n<4000){b.update();n++;}var res="forge placed -> in: "+reqs.join(",")+" -> crafted "+b.items.get(g.outputItem.item)+" "+g.outputItem.item.name.substring(10)+" after "+n+" ticks"+(b.items.get(g.outputItem.item)>0?"":" printed nothing");b.tile.setNet(Blocks.air);res' 3
send 'js var p=Vars.content.planet("'$P'aurelia");var sec=p.sectors.get(p.startSector);Vars.logic.reset();Vars.world.loadSector(sec);Vars.state.rules.sector=sec;Vars.logic.play();var f={},o={},w={},bad=0,badOre=0;Vars.world.tiles.eachTile(function(t){var fl=t.floor().name;f[fl.replace("'$P'","")]=(f[fl.replace("'$P'","")]||0)+1;var ov=t.overlay();if(ov!=null&&ov!=Blocks.air&&ov!=Blocks.spawn){o[ov.name.replace("'$P'","")]=(o[ov.name.replace("'$P'","")]||0)+1;if(!ov.name.startsWith("'$P'"))badOre++;}if(t.block().isStatic()){w[t.block().name.replace("'$P'","")]=(w[t.block().name.replace("'$P'","")]||0)+1;if(!t.block().name.startsWith("'$P'"))bad++;}if(!fl.startsWith("'$P'")&&fl!="air"&&fl!="empty"&&fl!="spawn")bad++;});var core=Vars.state.rules.defaultTeam.core();var items=[];core.items.each(function(i,a){items.push((i.name.startsWith("'$P'")?"":"VANILLA:")+i.name.replace("'$P'","")+"="+a);});"aurelia sector "+sec.id+" "+Vars.world.width()+"x"+Vars.world.height()+" floors="+JSON.stringify(f)+" ores="+JSON.stringify(o)+" walls="+JSON.stringify(w)+" vanilla terrain tiles="+bad+" vanilla ore tiles="+badOre+" core="+core.block.name+" stock: "+items.join(" ")' 12
send 'js var t=Vars.state.rules.defaultTeam;"unit cap: variable="+Vars.state.rules.unitCapVariable+" rules.unitCap="+Vars.state.rules.unitCap+" core modifier sum="+t.data().unitCap+" -> Units.getCap="+Units.getCap(t)+", can create glint="+Units.canCreate(t,Vars.content.unit("'$P'glint"))' 1
send 'js var u={},bad=[];Vars.state.rules.spawns.each(function(g){u[g.type.name.replace("'$P'","")]=1;if(!g.type.name.startsWith("'$P'"))bad.push(g.type.name);if(g.effect!=null&&!g.effect.name.startsWith("'$P'")&&g.effect!=StatusEffects.none)bad.push("effect:"+g.effect.name);});"aurelia waves: groups="+Vars.state.rules.spawns.size+" units="+Object.keys(u).join(",")+(bad.length?" VANILLA "+bad.join(" "):" (own units only)")' 1
send 'js var p=Vars.content.planet("'$P'aurelia");var tot=0,bad=[];var walk=function(t){if(t.content instanceof Block){tot++;var b=t.content;if(!(b.isVisible()&&b.environmentBuildable()&&b.supportsEnv(Vars.state.rules.env)&&b.isPlaceable()))bad.push(b.name);}t.children.each(walk);};walk(p.techTree);var fog=bad.filter(function(n){return Vars.content.block(n).buildVisibility==BuildVisibility.fogOnly;});bad=bad.filter(function(n){return fog.indexOf(n)<0;});"aurelia env="+Vars.state.rules.env+" buildable: "+(tot-bad.length-fog.length)+"/"+tot+" + fog-of-war-only: "+fog.join(" ")+(bad.length?" NOT BUILDABLE: "+bad.join(" "):" -> everything else buildable")' 2
send 'js Vars.state.rules.unitCap=200;"test unit cap raised"' 1

# ---- every 3D unit spawns, moves, fires
send 'js var c=Vars.state.rules.defaultTeam.core();global.cx=c.x;global.cy=c.y;var s="";var ft=global.free(c.x,c.y,9);global.gx=ft.worldx();global.gy=ft.worldy();["lumen-pilot","glint","aurora-guard","aurora-heavy","shard-rover","aurite-bulwark","lensing","ergosphere","accretor","citadel","aegis-titan","pyroclast-titan"].forEach(function(n,i){var t=Vars.content.unit("'$P'"+n);var u=t.spawn(Vars.state.rules.defaultTeam,global.gx-40,global.gy-40+i*10);u.controller(extend(AIController,{updateUnit:function(){}}));var x0=u.x;var v=new Vec2();for(var k=0;k<90;k++){v.trns(0,u.speed());u.moveAt(v);u.aim(u.x+60,u.y+60);u.lookAt(t.omniMovement?45:0);u.controlWeapons(true,true);u.update();}var sh=0;for(var m=0;m<u.mounts.length;m++)sh+=u.mounts[m].totalShots;var extra=(t instanceof Packages.blackhole.g3d.Walker3D)?(" vanillaLegs="+u.legs().length+" feet="+t.state(u).planted):"";s+=n+"[moved "+global.F(u.x-x0,0)+" shots "+sh+" hp "+global.F(u.health,0)+extra+(u.dead?" DEAD":"")+"] ";u.isShooting=false;u.kill();});s' 4
send 'js var s="";Vars.content.units().each(function(t){if(!t.name.startsWith("'$P'"))return;t.weapons.each(function(w){if(w.shoot instanceof ShootAlternate&&w.barrelSpread!==undefined&&w.barrelSpread>0)s+=t.name.substring(10)+":"+w.name+" spread="+global.F(w.shoot.spread,2)+" ";});});"twin-barrel patterns follow the models: "+s' 1
send 'js var ft=global.free(global.cx,global.cy,6);var t=Vars.content.unit("'$P'tide-skiff");var w=null;Vars.world.tiles.eachTile(function(q){if(w==null&&q.floor().isLiquid&&q.build==null&&!q.solid())w=q;});global.wtile=w;var s="";["tide-skiff","tide-warden"].forEach(function(n){var t=Vars.content.unit("'$P'"+n);var u=t.spawn(Vars.state.rules.defaultTeam,w.worldx(),w.worldy());u.controller(extend(AIController,{updateUnit:function(){}}));for(var k=0;k<60;k++){u.aim(u.x+60,u.y+60);u.controlWeapons(true,true);u.update();}var sh=0;for(var m=0;m<u.mounts.length;m++)sh+=u.mounts[m].totalShots;s+=n+"[naval="+t.naval+" on "+u.floorOn().name.substring(10)+" shots "+sh+(u.dead?" DEAD":"")+"] ";u.kill();});s' 3

# ---- fabricator prints the new heavy gunship, tide dock prints a skiff
send 'js var t=Vars.state.rules.defaultTeam;var c={x:global.cx,y:global.cy};var tl=null;for(var r=8;r<60&&tl==null;r+=2)for(var a=0;a<360&&tl==null;a+=15){var q=Vars.world.tileWorld(c.x+Math.cos(a/57.3)*r*8,c.y+Math.sin(a/57.3)*r*8);if(q==null)continue;var ok=true;for(var dx=-2;dx<=3&&ok;dx++)for(var dy=-2;dy<=3&&ok;dy++){var z=Vars.world.tile(q.x+dx,q.y+dy);if(z==null||z.solid()||z.floor().isDeep()||z.build!=null)ok=false;}if(ok)tl=q;}tl.setNet(Vars.content.block("'$P'aurelia-fabricator"),t,0);global.fx=tl.x;global.fy=tl.y;var b=tl.build;var pi=0;for(var i=0;i<b.block.plans.size;i++){if(b.block.plans.get(i).unit.name=="'$P'aurora-heavy")pi=i;}b.currentPlan=pi;var pl=b.block.plans.get(pi);pl.requirements.forEach(function(s){b.items.add(s.item,s.amount);});b.power.status=1;var n=0;while(b.payload==null&&n<Math.ceil(pl.time)*3){b.update();n++;}"fabricator plans: "+b.block.plans.map(function(p){return p.unit.name.substring(10)+"["+p.requirements.map(function(q){return q.item.name.substring(10)+"x"+q.amount}).toString(",")+"]"}).toString(" ")+" -> printed "+(b.payload==null?"nothing":b.payload.unit.type.name)+" after "+n+" ticks"' 3
send 'js var t=Vars.state.rules.defaultTeam;var tl=null;Vars.world.tiles.eachTile(function(q){if(tl!=null)return;var ok=true;for(var dx=-1;dx<=1&&ok;dx++)for(var dy=-1;dy<=1&&ok;dy++){var z=Vars.world.tile(q.x+dx,q.y+dy);if(z==null||!z.floor().isLiquid||z.build!=null||z.solid())ok=false;}if(ok)tl=q;});tl.setNet(Vars.content.block("'$P'tide-dock"),t,0);var b=tl.build;b.currentPlan=0;var pl=b.block.plans.get(0);pl.requirements.forEach(function(s){b.items.add(s.item,s.amount);});b.power.status=1;var n=0;while(b.payload==null&&n<Math.ceil(pl.time)*3){b.update();n++;}"tide dock on "+tl.floor().name.substring(10)+" printed "+(b.payload==null?"nothing":b.payload.unit.type.name)+" after "+n+" ticks"' 3

# ---- 7.3: the curvature singularity turret and every piece of its code are gone
send 'js var gone=["warp-s","warp-e"].map(function(n){return n+"="+(Vars.content.block("'$P'"+n)==null)}).join(" ");var st=Vars.content.statusEffects().find(function(s){return s.name=="'$P'warp-field"});var cls=(""+Packages.sixfold.WarpTurret).indexOf("JavaPackage")<0;"curvature singularity removed: "+gone+" warp-field status removed="+(st==null)+" WarpTurret class removed="+(cls==false)' 1

# ---- 7.3: the harmonic relay no longer crashes on placement (Groups.build has no quadtree -> intersect() was a null tree),
# ---- and a real three-anchor formation makes it synthesize concord cores
send 'js var t=Vars.state.rules.defaultTeam;var c=t.core();var q=global.free(c.x,c.y,3);q.setNet(Vars.content.block("'$P'harmonic-relay"),t,0);global.rx=q.x;global.ry=q.y;var b=q.build;var n=0;for(;n<300;n++){b.power.status=1;b.update();}"harmonic relay placed at "+q.x+","+q.y+" -> alive after "+n+" ticks, build="+b.getClass().getSimpleName()+" links="+b.linked+" items="+b.items.total()' 2
send 'js var t=Vars.state.rules.defaultTeam;var b=Vars.world.tile(global.rx,global.ry).build;var an=Vars.content.block("'$P'rift-anchor");var placed=0,info="";for(var i=0;i<3;i++){var a=global.free(b.x,b.y,2);if(a==null)continue;a.setNet(an,t,0);if(a.build!=null){a.build.stability=1;placed++;info+=" d="+global.F(b.dst(a.build),0);}}var seen=0,anch=0;Vars.indexer.eachBlock(b,230,function(o){return true;},function(o){seen++;if(o.block.name.indexOf("rift-anchor")>=0)anch++;});for(var k=0;k<120;k++){b.power.status=1;b.update();}"anchors placed="+placed+info+" indexer sees "+seen+" own buildings ("+anch+" anchors) -> relay links="+b.linked' 3
send 'js var b=Vars.world.tile(global.rx,global.ry).build;var got=0,m=0;while(got==0&&m<6000){b.power.status=1;if(m%60==0){Vars.indexer.eachBlock(b,230,function(o){return o.block.name.indexOf("rift-anchor")>=0;},function(o){o.stability=1;});}b.update();got=b.items.total();m++;}"three-anchor formation -> links="+b.linked+" alignment="+global.F(b.alignment,2)+" -> synthesized "+got+" concord core after "+m+" ticks"+(got>0?"":" printed nothing")' 4

# ---- 7.3: lumen extractor / cell / conduit draw through their own 3D code instead of vanilla sprite paths ("oh no")
send 'js var ex=Vars.content.block("'$P'lumen-extractor"),ce=Vars.content.block("'$P'lumen-cell"),cd=Vars.content.block("'$P'lumen-conduit");"extractor build="+ex.buildType.get().getClass().getSimpleName()+"; cell drawer="+ce.drawer.getClass().getSimpleName()+" model="+(ce.model!=null)+"; conduit build="+cd.buildType.get().getClass().getSimpleName()' 1
send 'js var t=Vars.state.rules.defaultTeam;var c=t.core();var q=global.free(c.x,c.y,2);var cd=Vars.content.block("'$P'lumen-conduit");q.setNet(cd,t,0);var b=q.build;var liq=Vars.content.liquid("'$P'lumen-plasma");b.liquids.add(liq,8);for(var i=0;i<30;i++)b.update();var res="conduit "+b.getClass().getSimpleName()+" carries "+global.F(b.liquids.currentAmount(),2)+"/"+cd.liquidCapacity+" "+b.liquids.current().name.substring(10)+" smoothLiquid="+global.F(b.smoothLiquid,3)+" -> drawn alpha "+global.F(Math.min(1,0.35+Math.max(b.smoothLiquid,b.liquids.currentAmount()/cd.liquidCapacity)*0.65),2);b.tile.setNet(Blocks.air);res' 2


send 'js var u=Vars.content.unit("'$P'pyroclast-titan");var w=u.weapons.get(0);"pyroclast titan main gun: "+w.name.substring(10)+" rotate="+w.rotate+" rotateSpeed="+w.rotateSpeed+" mount=("+global.F(w.x,2)+","+global.F(w.y,2)+") shoot=("+global.F(w.shootX,2)+","+global.F(w.shootY,2)+") muzzleZ="+global.F(w.muzzleZ,2)+" barrelSpread="+global.F(w.barrelSpread,2)+" pattern="+w.shoot.getClass().getSimpleName()+" bullet="+w.bullet.getClass().getSimpleName()+" speed="+w.bullet.speed+" range="+global.F(w.bullet.range,0)' 1

# ---- 7.3 merge: every mod recipe is priced in Aurelia resources, nothing vanilla left anywhere
send 'js var bad=[],blocks=0,plans=0,recipes=0;Vars.content.blocks().each(function(b){if(!b.name.startsWith("'$P'"))return;blocks++;if(b.requirements)b.requirements.forEach(function(q){if(!q.item.name.startsWith("'$P'"))bad.push(b.name+":req:"+q.item.name);});if(b instanceof Packages.mindustry.world.blocks.units.UnitFactory&&b.plans!=null)b.plans.each(function(pl){plans++;pl.requirements.forEach(function(q){if(!q.item.name.startsWith("'$P'"))bad.push(b.name+":plan:"+q.item.name);});});if(b.consumers)b.consumers.forEach(function(c){if(c instanceof ConsumeItems){recipes++;c.items.forEach(function(q){if(!q.item.name.startsWith("'$P'"))bad.push(b.name+":in:"+q.item.name);});}});});"merge costs: "+blocks+" mod blocks, "+plans+" unit plans, "+recipes+" item recipes -> vanilla items used="+bad.length+(bad.length?" VANILLA "+bad.slice(0,20).join(" "):"")' 2

# ---- 7.3 merge: every researchable mod content has a node in the Aurelia tree
send 'js var p=Vars.content.planet("'$P'aurelia");var inTree={},n=0;var walk=function(t){n++;inTree[t.content.name]=1;t.children.each(walk);};walk(p.techTree);var missing=[],total=0;Vars.content.blocks().each(function(b){if(!b.name.startsWith("'$P'"))return;if(b.buildVisibility==BuildVisibility.hidden||b.buildVisibility==BuildVisibility.debugOnly||b.buildVisibility==BuildVisibility.sandboxOnly)return;if(b.requirements==null||b.requirements.length==0)return;total++;if(!inTree[b.name])missing.push(b.name);});Vars.content.units().each(function(u){if(!u.name.startsWith("'$P'")||u.isHidden())return;total++;if(!inTree[u.name])missing.push(u.name);});Vars.content.items().each(function(i){if(!i.name.startsWith("'$P'"))return;total++;if(!inTree[i.name])missing.push(i.name);});"merge tree: aurelia nodes="+n+" covering "+(total-missing.length)+"/"+total+" researchable mod contents"+(missing.length?" Missing "+missing.join(" "):"")' 2

# ---- 7.3 merge: the whole mod is buildable on Aurelia (env + planet visibility)
send 'js var p=Vars.content.planet("'$P'aurelia");var env=p.defaultEnv;var no=[],ok=0,shown=0;Vars.content.blocks().each(function(b){if(!b.name.startsWith("'$P'")||!b.isVisible())return;if(b.isOnPlanet(p))shown++;if((b.envEnabled&env)!=0&&(b.envRequired&~env)==0)ok++;else no.push(b.name);});"aurelia merge: "+shown+" mod blocks shown on aurelia, "+ok+" pass the env filter"+(no.length?" NOT BUILDABLE "+no.join(" "):"")' 2

# ---- 7.3: turret heads are live 3D meshes (no -heads sprite sheet exists any more), built up front
