send 'js var P="blackhole-";var cmd=Vars.content.block(P+"astro-commander");var cl=cmd!=null?cmd.getClass().getClassLoader():Vars.content.unit(P+"astro-detainer").getClass().getClassLoader();var load=function(n){try{cl.loadClass(n);return true}catch(e){return false}};var ui=load("astro.ui.AstroUI"),ai=load("astro.ai.TacticalBrain"),pv=load("astro.ui.PanelView"),tc=load("astro.content.TacticalCommander");var warp=false;try{var c=cl.loadClass("astro.ui.AstroUI");var ms=c.getDeclaredMethods();for(var i=0;i<ms.length;i++)if(ms[i].getName()=="warpAim"||ms[i].getName()=="drawPick")warp=true;}catch(e){}var nm=Core.bundle.get("block."+P+"astro-commander.name");var st=Core.bundle.get("astro.settings.title"),pt=Core.bundle.get("astro.ui.title");var fab=Core.bundle.get("block."+P+"astro-fabricator.name");var bad=[];if(!(ui&&ai&&pv&&tc))bad.push("astro ui/ai classes missing");if(!warp)bad.push("warp targeting missing");if(cmd==null)bad.push("tactical command block missing");if(nm.indexOf("???")>=0||st.indexOf("???")>=0||pt.indexOf("???")>=0)bad.push("astro bundle keys missing");"v8.3 astro restored: AstroUI="+ui+" PanelView="+pv+" TacticalBrain="+ai+" TacticalCommander="+tc+" warp targeting="+warp+" command block="+(cmd!=null?cmd.name.substring(10)+"["+cmd.size+"x"+cmd.size+"]":"none")+" name=\""+nm+"\" panel=\""+pt+"\" settings=\""+st+"\" factory=\""+fab+"\""+(bad.length?" BAD "+bad.join(" "):" -> panel, settings, warp picker and the tactical brain are all back")' 2
